1	/**
2	 * Pure helpers for the claim-code inventory screen (Functional Core — no IPC).
3	 *
4	 * The relay reports every minted code with a derived status; the screen splits them
5	 * into the actionable set (outstanding live credentials) and the historical record.
6	 */
7	import type { ClaimCodeEntry } from '$lib/ipc';
8	
9	export interface PartitionedCodes {
10	  /** Live credentials — `pending` codes the operator can still share or revoke. */
11	  outstanding: ClaimCodeEntry[];
12	  /** The historical record — redeemed, expired, and revoked codes. */
13	  history: ClaimCodeEntry[];
14	}
15	
16	/**
17	 * Split an inventory page (or accumulated pages) into outstanding vs history,
18	 * preserving the relay's newest-first order within each group. Only `pending` is
19	 * outstanding: every other status is terminal or dead and belongs to history.
20	 */
21	export function partitionCodes(codes: ClaimCodeEntry[]): PartitionedCodes {
22	  const outstanding: ClaimCodeEntry[] = [];
23	  const history: ClaimCodeEntry[] = [];
24	  for (const entry of codes) {
25	    (entry.status === 'pending' ? outstanding : history).push(entry);
26	  }
27	  return { outstanding, history };
28	}
29	
30	/**
31	 * The chip rendering for each relay-reported status — tone + label, never color
32	 * alone (the StatusChip adds the glyph). `redeemed` is the success story (the code
33	 * did its job); `revoked` is the operator's kill; `expired` is neutral clock death.
34	 */
35	export function chipFor(status: ClaimCodeEntry['status']): {
36	  chip: 'pending' | 'ready' | 'info' | 'revoked';
37	  label: string;
38	} {
39	  switch (status) {
40	    case 'pending':
41	      return { chip: 'pending', label: 'pending' };
42	    case 'redeemed':
43	      return { chip: 'ready', label: 'redeemed' };
44	    case 'expired':
45	      return { chip: 'info', label: 'expired' };
46	    case 'revoked':
47	      return { chip: 'revoked', label: 'revoked' };
48	    default: {
49	      // The wire carries status as a plain string, and this app pairs with relays of
50	      // potentially different versions — an unfamiliar status must render as a visible
51	      // unknown, never a blank chip. `never` keeps the compile-time exhaustiveness check.
52	      const unknown: never = status;
53	      return { chip: 'info', label: `unknown (${String(unknown)})` };
54	    }
55	  }
56	}
57	
58	/**
59	 * The one timeline line a collapsed row shows: the fact that ended the code's life,
60	 * or its expiry deadline while it is still pending. Relay timestamps verbatim —
61	 * literal truth, no relative-time gloss.
62	 */
63	export function timelineLine(entry: ClaimCodeEntry): string {
64	  switch (entry.status) {
65	    case 'redeemed':
66	      return `redeemed ${entry.redeemedAt ?? 'at an unknown time'}`;
67	    case 'revoked':
68	      return `revoked ${entry.revokedAt ?? 'at an unknown time'}`;
69	    case 'expired':
70	      return `expired ${entry.expiresAt}`;
71	    case 'pending':
72	      return `expires ${entry.expiresAt}`;
73	    default: {
74	      // Version-skew guard (see chipFor): an unknown status still gets a factual line.
75	      const unknown: never = entry.status;
76	      void unknown;
77	      return `minted ${entry.createdAt}`;
78	    }
79	  }
80	}
