48	/// `POST /v1/accounts/claim-codes` — admin-only claim-code minting.
49	///
50	/// Auth runs first, over the raw body, so the canonical signature envelope can bind
51	/// the exact request bytes (and so unauthenticated callers learn nothing about the
52	/// body schema). Only after auth passes is the body parsed as JSON — using
53	/// `Json::from_bytes` so malformed/invalid bodies return the same 400/422 statuses
54	/// the `Json` extractor produced before this route accepted device signatures.
55	pub async fn claim_codes(
56	    State(state): State<AppState>,
57	    method: Method,
58	    uri: Uri,
59	    headers: HeaderMap,
60	    body: Bytes,
61	) -> Result<Json<ClaimCodesResponse>, Response> {
62	    require_admin_json(method.as_str(), uri.path(), &headers, &body, &state).await?;
63	
64	    let Json(payload) =
65	        Json::<ClaimCodesRequest>::from_bytes(&body).map_err(IntoResponse::into_response)?;
66	
67	    claim_codes_inner(&state, payload)
68	        .await
69	        .map_err(IntoResponse::into_response)
