72	async fn claim_codes_inner(
73	    state: &AppState,
74	    payload: ClaimCodesRequest,
75	) -> Result<Json<ClaimCodesResponse>, ApiError> {
76	    // --- Validate input ---
77	    if payload.count == 0 || payload.count > MAX_COUNT {
78	        return Err(ApiError::new(
79	            ErrorCode::InvalidClaim,
80	            format!("count must be between 1 and {MAX_COUNT}"),
81	        ));
82	    }
83	    if payload.expires_in_hours == 0 {
84	        return Err(ApiError::new(
85	            ErrorCode::InvalidClaim,
86	            "expiresInHours must be greater than 0",
87	        ));
88	    }
89	
90	    // --- Generate unique codes and insert in a single transaction ---
91	    // Attempt up to 3 times total (2 retries) on the rare event of a uniqueness
92	    // conflict with an existing DB row (probability ≈ existing_codes / 36^6 per code).
93	    for attempt in 0..3_usize {
94	        let codes = generate_unique_codes(payload.count as usize);
95	        match insert_claim_codes(&state.db, &codes, payload.expires_in_hours).await {
96	            Ok(()) => return Ok(Json(ClaimCodesResponse { codes })),
97	            Err(e) if is_unique_violation(&e) => {
98	                tracing::warn!(attempt, "claim code uniqueness conflict; retrying");
99	                continue;
100	            }
101	            Err(e) => {
102	                tracing::error!(error = %e, "failed to insert claim codes");
103	                return Err(ApiError::new(
104	                    ErrorCode::InternalError,
105	                    "failed to store claim codes",
106	                ));
107	            }
108	        }
109	    }
110	
111	    Err(ApiError::new(
112	        ErrorCode::InternalError,
113	        "failed to generate unique claim codes after retries",
114	    ))
115	}
