152	/// Collapse a row's lifecycle timestamps into the one status word the operator sees.
153	///
154	/// The states can overlap on a real row (a code redeemed before its expiry passed is now
155	/// both "redeemed" and past `expires_at`; a revoked code keeps aging toward expiry), so
156	/// this function owns the precedence order.
157	/// Precedence: the terminal events win over the clock. A redeemed or revoked code reports
158	/// that event forever — never "expired", even once `expires_at` passes — because the event
159	/// is the fact the operator acts on (a signup happened / a kill was ordered). `expired`
160	/// and `pending` apply only to codes nothing ever happened to. (`redeemed_at` and
161	/// `revoked_at` are never both set: the revoke UPDATE refuses a redeemed code and every
162	/// redemption UPDATE refuses a revoked one.)
163	fn derive_status(row: &crate::db::claim_codes::ClaimCodeRow) -> &'static str {
164	    if row.redeemed_at.is_some() {
165	        "redeemed"
166	    } else if row.revoked_at.is_some() {
167	        "revoked"
168	    } else if row.is_expired {
169	        "expired"
170	    } else {
171	        "pending"
172	    }
173	}
