175	/// `GET /v1/accounts/claim-codes` — admin-only claim-code inventory.
176	///
177	/// Pages the full mint history newest-first on the immutable `(created_at, code)` keyset
178	/// (stable across VACUUM, unlike this TEXT-keyed table's implicit rowid — and a table
179	/// rebuild for an INTEGER key is off the table: `pending_accounts.claim_code` FK-references
180	/// `claim_codes (code)`), each row carrying its derived
181	/// lifecycle status. A minted-but-unredeemed code is a live signup credential — this is the
182	/// operator's view of what is outstanding. Admin-authed: the master token **or** an active
183	/// companion-app device's signed request ([`require_admin`]); a GET signs the empty body.
184	pub async fn list_claim_code_inventory(
185	    State(state): State<AppState>,
186	    Query(params): Query<ListClaimCodesParams>,
187	    method: Method,
188	    uri: Uri,
189	    headers: HeaderMap,
190	    body: Bytes,
191	) -> Result<Json<ListClaimCodesResponse>, ApiError> {
192	    require_admin(method.as_str(), uri.path(), &headers, &body, &state).await?;
193	
194	    if params.limit == 0 || params.limit > MAX_LIST_LIMIT {
195	        return Err(ApiError::new(
196	            ErrorCode::InvalidRequest,
197	            format!("limit must be between 1 and {MAX_LIST_LIMIT}"),
198	        ));
199	    }
200	    // The opaque cursor is the previous page's last `created_at|code`; created_at never
201	    // contains '|' and codes are uppercase alphanumeric, so the first '|' is the seam.
202	    let cursor = params
203	        .cursor
204	        .as_deref()
205	        .map(|raw| {
206	            raw.split_once('|')
207	                .ok_or_else(|| ApiError::new(ErrorCode::InvalidRequest, "malformed cursor"))
208	        })
209	        .transpose()?;
210	
211	    let rows = list_claim_codes(&state.db, cursor, params.limit)
212	        .await
213	        .map_err(|e| {
214	            tracing::error!(error = %e, "failed to list claim codes");
215	            ApiError::new(ErrorCode::InternalError, "failed to list claim codes")
216	        })?;
217	
218	    // A short page means the history is exhausted; a full page may have more.
219	    let cursor = (rows.len() == params.limit as usize)
220	        .then(|| rows.last().map(|r| format!("{}|{}", r.created_at, r.code)))
221	        .flatten();
222	    let codes = rows
223	        .iter()
224	        .map(|row| ClaimCodeView {
225	            code: row.code.clone(),
226	            status: derive_status(row),
227	            created_at: row.created_at.clone(),
228	            expires_at: row.expires_at.clone(),
229	            redeemed_at: row.redeemed_at.clone(),
230	            revoked_at: row.revoked_at.clone(),
231	        })
232	        .collect();
233	
234	    Ok(Json(ListClaimCodesResponse { codes, cursor }))
235	}
