/// One in-flight transfer as the operator sees it.
///
/// Deliberately excludes the 6-char `code`: unlike a claim code (a signup credential
/// meant to be shared), a transfer code is a live account-takeover credential — whoever
/// presents it at `/v1/transfer/accept` receives device credentials for the DID. The
/// operator needs visibility into the pending state, never the secret itself.
#[derive(Debug, PartialEq, Eq)]
pub struct InflightTransferRow {
    pub id: String,
    pub did: String,
    /// One associated handle (if any), for operator readability.
    pub handle: Option<String>,
    pub status: String,
    pub created_at: String,
    pub expires_at: String,
    pub accepted_at: Option<String>,
    /// Platform of the device that accepted the transfer, when one has.
    pub accepted_device_platform: Option<String>,
}

/// List the transfers an operator can still interrupt, newest first.
///
/// "In flight" is deliberately asymmetric about the clock: a lapsed `pending` transfer is
/// excluded (acceptance requires `expires_at > now`, so nothing can happen to it — it is
/// inert until a later initiate sweeps it to `expired`), but a lapsed `accepted`/
/// `completing` transfer stays visible because completion (`mark_transfer_complete`) has
/// no expiry predicate — the target device's credential is live and the swap can still
/// finish. That still-completable state is exactly what the operator needs to see.
///
/// Pages on the immutable `(created_at, id)` keyset (cursor exclusive, same shape as the
/// claim-code inventory).
pub async fn list_inflight_transfers(
    db: &SqlitePool,
    cursor: Option<(&str, &str)>,
    limit: u32,
) -> Result<Vec<InflightTransferRow>, sqlx::Error> {
    let (cursor_created_at, cursor_id) = match cursor {
        Some((created_at, id)) => (Some(created_at), Some(id)),
        None => (None, None),
    };
    type Row = (
        String,
        String,
        Option<String>,
        String,
        String,
        String,
        Option<String>,
        Option<String>,
    );
    let rows = sqlx::query_as::<_, Row>(
        "SELECT t.id, t.did, \
                (SELECT h.handle FROM handles h WHERE h.did = t.did \
                 ORDER BY h.created_at ASC, h.handle ASC LIMIT 1), \
                t.status, t.created_at, t.expires_at, t.accepted_at, \
                (SELECT d.platform FROM transfer_devices d WHERE d.id = t.accepted_device_id) \
         FROM transfers t \
         WHERE (t.status IN ('accepted', 'completing') \
                OR (t.status = 'pending' AND t.expires_at > datetime('now'))) \
           AND (? IS NULL OR (t.created_at, t.id) < (?, ?)) \
         ORDER BY t.created_at DESC, t.id DESC LIMIT ?",
    )
    .bind(cursor_created_at)
    .bind(cursor_created_at)
    .bind(cursor_id)
    .bind(limit)
    .fetch_all(db)
    .await?;

    Ok(rows
        .into_iter()
        .map(
            |(id, did, handle, status, created_at, expires_at, accepted_at, platform)| {
                InflightTransferRow {
                    id,
                    did,
                    handle,
                    status,
                    created_at,
                    expires_at,
                    accepted_at,
                    accepted_device_platform: platform,
                }
            },
        )
        .collect())
}

/// Mark an active transfer operator-cancelled.
///
/// Guarded on the active states so a terminal row (`complete`/`expired`/`cancelled`)
/// is never rewritten — the caller classifies a 0-row update by re-reading the status.
/// `cancelled` is terminal by construction: both partial unique indexes enumerate the
/// active statuses, so a cancelled row frees the per-DID and per-code slots exactly
/// like `complete`/`expired`, and every accept/complete lookup filters it out.
pub async fn mark_transfer_cancelled(
    tx: &mut SqliteTransaction<'_>,
    transfer_id: &str,
) -> Result<u64, sqlx::Error> {
    let updated = sqlx::query(
        "UPDATE transfers SET status = 'cancelled' \
         WHERE id = ? AND status IN ('pending', 'accepted', 'completing')",
    )
    .bind(transfer_id)
    .execute(&mut **tx)
    .await?;

    Ok(updated.rows_affected())
}

/// Tombstone a single transfer-device credential (V030 doctrine: the row survives as
/// the audit record; `transfer_device_token_exists` stops honoring it immediately).
pub async fn revoke_transfer_device(
    tx: &mut SqliteTransaction<'_>,
    device_id: &str,
) -> Result<u64, sqlx::Error> {
    let updated = sqlx::query(
        "UPDATE transfer_devices SET revoked_at = datetime('now') \
         WHERE id = ? AND revoked_at IS NULL",
    )
    .bind(device_id)
    .execute(&mut **tx)
    .await?;
    Ok(updated.rows_affected())
}

/// Append a transfer audit event.

/// Outcome of an operator cancelling an in-flight transfer.
#[derive(Debug, PartialEq, Eq)]
pub enum CancelOutcome {
    /// This call cancelled the transfer. Reports whether an accepted target device
    /// credential existed and was tombstoned along the way.
    Cancelled { revoked_device_credential: bool },
    /// The transfer was already cancelled — idempotent success for the caller.
    AlreadyCancelled,
    /// The transfer is terminal in a state cancel must not rewrite (`complete`, or
    /// `expired` — including a lapsed pending row swept during this call). Carries the
    /// status so the caller can name it in the conflict response.
    Terminal { status: String },
    /// No transfer with this id exists.
    NotFound,
}

/// Cancel an in-flight transfer on the operator's authority.
///
/// One transaction: a lapsed pending row is first swept to `expired` (so the outcome
/// reports the truth rather than "cancelling" a transfer that already died of clock),
/// then an active row is flipped to `cancelled`, the accepted target device credential —
/// if the transfer got that far — is tombstoned (`revoked_at`; without this, "cancelling"
/// an accepted transfer would leave the new device authenticated via
/// `transfer_device_token_exists`), and a `transfer.cancelled` audit event is appended.
///
/// Deliberately conservative about scope: the account's existing sessions are untouched.
/// In the benign case those are the legitimate user's source device; an operator who
/// believes the account itself is compromised composes this with the credential-sweep
/// route (`/v1/admin/accounts/{id}/revoke-credentials`).
pub async fn cancel_transfer(
    db: &SqlitePool,
    transfer_id: &str,
) -> Result<CancelOutcome, sqlx::Error> {
    let mut tx = db.begin().await?;

    crate::db::transfers::expire_pending_transfer_if_elapsed(&mut tx, transfer_id).await?;

    let Some(row) = crate::db::transfers::transfer_by_id(&mut tx, transfer_id).await? else {
        tx.commit().await?;
        return Ok(CancelOutcome::NotFound);
    };

    match row.status.as_str() {
        "pending" | "accepted" | "completing" => {}
        "cancelled" => {
            tx.commit().await?;
            return Ok(CancelOutcome::AlreadyCancelled);
        }
        _ => {
            tx.commit().await?;
            return Ok(CancelOutcome::Terminal { status: row.status });
        }
    }

    let updated = crate::db::transfers::mark_transfer_cancelled(&mut tx, &row.id).await?;
    if updated != 1 {
        // The guarded UPDATE observed the same row this transaction just read as active;
        // on the single-connection pool nothing can have raced in between, so a miss here
        // is a bug, not a state to report politely.
        return Err(sqlx::Error::RowNotFound);
    }

    let mut revoked_device_credential = false;
    if let Some(device_id) = &row.accepted_device_id {
        revoked_device_credential =
            crate::db::transfers::revoke_transfer_device(&mut tx, device_id).await? > 0;
    }

    crate::db::transfers::insert_transfer_audit_event(
        &mut tx,
        &Uuid::new_v4().to_string(),
        &row.id,
        &row.did,
        "transfer.cancelled",
        None,
    )
    .await?;

    tx.commit().await?;
    Ok(CancelOutcome::Cancelled {
        revoked_device_credential,
    })
}

