import { chipFor, partitionCodes, timelineLine } from './claim-codes';
import type { ClaimCodeEntry } from './ipc';

function entry(overrides: Partial<ClaimCodeEntry> & Pick<ClaimCodeEntry, 'code' | 'status'>): ClaimCodeEntry {
